    76	function createSafeInvocation(
    77		name: string,
    78		args: Record<string, unknown>,
    79		taxonomy: ToolTelemetryMetadata | undefined,
    80	) {
    81		const argumentKeys = structuralArgumentKeys.filter((key) => key in args);
    82		const argumentPresence: Record<string, true> = {};
    83		const numericArgumentBuckets: Record<
    84			string,
    85			ReturnType<typeof bucketCount>
    86		> = {};
    87		const booleanArguments: Record<string, boolean> = {};
    88	
    89		for (const key of argumentKeys) {
    90			const value = args[key];
    91			if (
    92				key in PRESENCE_ARGUMENT_KEYS &&
    93				value !== null &&
    94				value !== undefined
    95			) {
    96				argumentPresence[key] = true;
    97			}
    98			if (key in NUMERIC_ARGUMENT_KEYS && typeof value === "number") {
    99				numericArgumentBuckets[key] = bucketCount(value);
   100			}
   101			if (key in BOOLEAN_ARGUMENT_KEYS && typeof value === "boolean") {
   102				booleanArguments[key] = value;
   103			}
   104		}
   105	
   106		return {
   107			name,
   108			taxonomy,
   109			argumentKeys,
   110			argumentPresence,
   111			numericArgumentBuckets,
   112			booleanArguments,
   113			argumentKeyCountBucket: bucketCount(Object.keys(args).length),
   114		};
   115	}
