   141	export interface CreateToolRuntimeOptions {
   142		client: HevyClient | null;
   143		/** Unbound client retained across nested execution scopes. */
   144		baseClient?: HevyClient | null;
   145		operations?: HevyOperations;
   146		catalog: ExerciseTemplateCatalog;
   147		logger?: McpClientLogger;
   148		createHandler?: ToolHandlerFactory;
   149		observer?: ToolObserver;
