   156	export const defaultHandlerFactory: ToolHandlerFactory = <
   157		TParams extends Record<string, unknown>,
   158	>(
   159		fn: ToolHandler<TParams>,
   160		context: string,
   161	) => withErrorHandling(fn, context);
   162	
   163	export function createToolRuntime({
   164		client,
   165		baseClient,
   166		operations,
   167		catalog,
   168		logger,
   169		createHandler = defaultHandlerFactory,
   170		observer,
   171		execution,
   172		executionTimeoutMs = DEFAULT_API_TIMEOUT_MS,
   173		executionDeadline,
   174		lifecycleSignal,
   175	}: CreateToolRuntimeOptions): ToolRuntime {
   176		const rawClient = baseClient ?? client;
   177		const resolvedOperations =
   178			operations ?? (rawClient ? createOperations(rawClient) : null);
   179		const effectiveExecutionDeadline = executionDeadline ?? execution?.deadline;
   180		const createObservedHandler: ToolHandlerFactory = <
   181			TParams extends Record<string, unknown>,
   182		>(
   183			fn: ToolHandler<TParams>,
   184			context: string,
   185			metadata?: ToolTelemetryMetadata,
   186		) =>
   187			createHandler<TParams>(
   188				async (args: TParams, requestContext?: ToolExecutionContext) => {
   189					let scope;
   190					try {
   191						scope = memoizeObservationScope(
   192							observer?.start(createSafeInvocation(context, args, metadata)),
   193						);
   194					} catch {
   195						scope = undefined;
   196					}
   197					const startedAt = Date.now();
   198					let handlerPromise: Promise<McpToolResponse> | undefined;
   199					const invokeHandler = () => {
   200						handlerPromise ??= Promise.resolve().then(() =>
   201							fn(args, requestContext),
   202						);
   203						return handlerPromise;
   204					};
   205					try {
   206						let runPromise: Promise<McpToolResponse>;
   207						if (scope) {
   208							try {
   209								runPromise = scope.run(invokeHandler);
   210							} catch {
   211								runPromise = invokeHandler();
   212							}
   213						} else {
   214							runPromise = invokeHandler();
   215						}
   216						const result = await runPromise.catch(invokeHandler);
   217						void scope?.finish({
   218							outcome: result.isError ? "returned_error" : "success",
   219							durationMs: Date.now() - startedAt,
   220							...(result.errorOutcome
   221								? { errorOutcome: result.errorOutcome }
   222								: {}),
   223							result: {
   224								isError: Boolean(result.isError),
   225								hasStructuredContent: result.structuredContent !== undefined,
   226								contentCountBucket: bucketCount(result.content.length),
   227								summary: getResultTelemetry(result),
   228							},
   229						});
   230						return result;
   231					} catch (error) {
   232						const policy = resolveErrorPolicy(error, "");
   233						void scope?.finish({
   234							outcome: "thrown_error",
   235							durationMs: Date.now() - startedAt,
   236							errorType: policy.type,
   237							error: policy.diagnostic,
   238						});
   239						throw error;
   240					}
   241				},
   242				context,
   243				metadata,
   244			);
   245		const observedHandlerFactory = observer
   246			? createObservedHandler
   247			: createHandler;
   248		const runtime: ToolRuntime = {
   249			client,
   250			catalog: execution
   251				? {
   252						get: (options) => catalog.get({ ...options, execution }),
   253						reset: () => catalog.reset(),
   254					}
   255				: catalog,
   256			logger,
   257			execution,
   258			executionTimeoutMs,
   259			executionDeadline: effectiveExecutionDeadline,
   260			lifecycleSignal,
   261			operations: resolvedOperations,
   262			createHandler: observedHandlerFactory,
   263			getClient: () => requireClient(client),
   264			getOperations: () =>
   265				resolvedOperations ?? createOperations(requireClient(client)),
   266			forExecution: (nextExecution) =>
   267				createToolRuntime({
   268					client: rawClient,
   269					baseClient: rawClient,
   270					operations: resolvedOperations ?? undefined,
   271					catalog,
   272					logger,
   273					createHandler,
   274					observer,
   275					execution: {
   276						...(nextExecution ?? {}),
   277						signal: mergeAbortSignals(lifecycleSignal, nextExecution?.signal),
   278						deadline:
   279							nextExecution?.deadline ??
   280							effectiveExecutionDeadline ??
   281							Date.now() + executionTimeoutMs,
   282					},
   283					executionTimeoutMs,
   284					executionDeadline:
   285						nextExecution?.deadline ?? effectiveExecutionDeadline,
   286					lifecycleSignal,
   287				}),
   288		};
   289		if (execution && client) {
   290			Object.assign(runtime, {
   291				client: bindClientExecution(requireClient(rawClient), execution),
   292				getClient: () => bindClientExecution(requireClient(rawClient), execution),
   293			});
   294		}
   295		return runtime;
   296	}
