    24		const unbracketed =
    25			host.startsWith("[") && host.endsWith("]") ? host.slice(1, -1) : host;
    26		const isBracketed = host.startsWith("[") || host.endsWith("]");
    27		const validHostname =
    28			/^(?=.{1,253}$)(?:[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?\.)*[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?$/u;
    29		if (
    30			host.length === 0 ||
    31			(isBracketed && !(host.startsWith("[") && host.endsWith("]"))) ||
    32			(isBracketed && isIP(unbracketed) !== 6) ||
    33			(!isBracketed && host.includes(":") && isIP(host) !== 6) ||
    34			(!isBracketed &&
    35				!host.includes(":") &&
    36				isIP(host) === 0 &&
    37				!validHostname.test(host)) ||
