    50	function parsePort(value: string): number {
    51		if (!/^[0-9]+$/u.test(value)) {
    52			throw new Error(`Invalid port: ${value}. Use an integer from 1 to 65535.`);
    53		}
    54		const port = Number(value);
    55		if (!Number.isSafeInteger(port) || port < 1 || port > 65535) {
    56			throw new Error(`Invalid port: ${value}. Use an integer from 1 to 65535.`);
    57		}
    58		return port;
    59	}
