    61	export function parseNodeCliOptions(args: string[]): NodeCliOptions {
    62		let transport: NodeTransport = "stdio";
    63		let host = DEFAULT_HOST;
    64		let port = DEFAULT_PORT;
    65		let transportExplicit = false;
    66		let hostExplicit = false;
    67		let portExplicit = false;
    68	
    69		for (let index = 0; index < args.length; index += 1) {
    70			const arg = args[index];
    71			if (!arg || ["--help", "-h", "--version", "-v"].includes(arg)) {
    72				continue;
    73			}
    74			switch (arg) {
    75				case "--transport": {
    76					const value = valueAfter(args, index, arg);
    77					index += 1;
    78					if (value !== "stdio" && value !== "http") {
    79						throw new Error(
    80							`Invalid transport: ${value}. Use either stdio or http.`,
    81						);
    82					}
    83					transport = value;
    84					transportExplicit = true;
    85					break;
    86				}
    87				case "--host":
    88					host = parseHost(valueAfter(args, index, arg));
    89					hostExplicit = true;
    90					index += 1;
    91					break;
    92				case "--port":
    93					port = parsePort(valueAfter(args, index, arg));
    94					portExplicit = true;
    95					index += 1;
    96					break;
    97				default:
    98					throw new Error(`Unknown option: ${arg}`);
    99			}
   100		}
   101	
   102		if (transport === "stdio" && (hostExplicit || portExplicit)) {
   103			throw new Error(
   104				"--host and --port can only be used with --transport http.",
