    38	export interface GracefulShutdownController {
    39		cleanup(): void;
    40		getShutdownPromise(): Promise<void> | undefined;
    41	}
    42	
    43	const shutdownSignals: ShutdownSignal[] = ["SIGINT", "SIGTERM"];
    44	
    45	// Long enough for normal stdio flushing, but bounded so unrelated handles or a
    46	// stalled close cannot keep a signal-terminated process alive indefinitely.
    47	export const FORCED_EXIT_TIMEOUT_MS = 5_000;
    48	
    49	export function flushStdout(
    50		stdout: FlushableStdout = process.stdout,
    51	): Promise<void> {
    52		return new Promise((resolve, reject) => {
    53			try {
    54				stdout.write("", (error) => {
    55					if (error) {
    56						reject(error);
    57						return;
    58					}
    59	
    60					resolve();
    61				});
    62			} catch (error) {
    63				reject(error);
    64			}
    65		});
    66	}
