414	export async function runServer(): Promise<void> {
415		const args = process.argv.slice(2);
416		const cliAction = getCliAction(args);
417		if (cliAction === "version") {
418			console.error(`${name} v${version}`);
419			return;
420		}
421		if (cliAction === "help") {
422			console.log(HELP_TEXT);
423			return;
424		}
425	
426		const options = parseNodeCliOptions(args);
427		if (options.transport === "stdio") {
428			await runStdioServer();
429			return;
430		}
431		const cleanupProcessExceptionTracking = installProcessExceptionTracking();
432		const lifecycleController = new AbortController();
433	
434		await tracer.startActiveSpan(
435			"mcp.server.run",
436			{
437				attributes: {
438					"mcp.span.category": "startup",
439					"mcp.transport": "http",
440				},
441			},
442			async (span) => {
443				let listening = false;
444				serverStartups.add(1, { version });
445				try {
446					const cfg = parseConfig(process.env);
447					assertApiKey(cfg.apiKey);
448					await validateApiKey(cfg.apiKey, lifecycleController.signal);
449					const handle = await startStreamableHttpServer(
450						options,
451						cfg.apiKey,
452						(params) =>
453							Promise.resolve(
454								buildServer(
455									params.apiKey,
456									"http",
457									mergeAbortSignals(
458										lifecycleController.signal,
459										params.lifecycleSignal,
460									),
461								),
462							),
463					);
464					listening = true;
465					console.error(
466						`Starting MCP server in HTTP mode at ${options.host}:${options.port}/mcp`,
467					);
468					scheduleUpdateCheck({
469						packageName: serviceName,
470						currentVersion: serviceVersion,
471					});
472					installGracefulShutdown({
473						target: handle,
474						cancel: lifecycleController,
475						onComplete: async () => {
476							cleanupProcessExceptionTracking();
477							await flushTelemetry();
478						},
479					});
480					span.setStatus({ code: SpanStatusCode.OK });
481				} catch (error) {
482					recordLifecycleFailure(
483						span,
484						error,
485						"run",
486						listening ? "runtime_failure" : "startup_failure",
487					);
488					recordMcpSessionTermination(listening ? "unknown" : "startup_failure");
489					span.setStatus({ code: SpanStatusCode.ERROR });
490					cleanupProcessExceptionTracking();
491					throw error;
492				} finally {
493					span.end();
494				}
495			},
496		);
497	}

