 92	function validateHostHeader(
 93		request: IncomingMessage,
 94		allowedHosts: Set<string>,
 95		port: number,
 96		allowAnyHostname = false,
 97	): boolean {
 98		const header = request.headers.host;
 99		if (!header || Array.isArray(header)) return false;
100		try {
101			const parsed = new URL(`http://${header}`);
102			if (
103				parsed.username ||
104				parsed.password ||
105				parsed.pathname !== "/" ||
106				parsed.search ||
107				parsed.hash ||
108				(!allowAnyHostname && (parsed.port ? Number(parsed.port) : 80) !== port)
109			) {
110				return false;
111			}
112			return (
113				allowAnyHostname ||
