150	function readBody(request: IncomingMessage): Promise<unknown> {
151		return new Promise((resolve, reject) => {
152			let size = 0;
153			let rejected = false;
154			const chunks: Buffer[] = [];
155			const onData = (chunk: Buffer | string) => {
156				const buffer = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
157				size += buffer.byteLength;
158				if (size > MAX_BODY_BYTES) {
159					if (!rejected) {
160						rejected = true;
161						request.removeListener("data", onData);
162						request.resume();
163						reject(new HttpRequestError(413, "Request body is too large."));
164					}
165					return;
166				}
167				if (!rejected) chunks.push(buffer);
168			};
169			request.on("data", onData);
170			request.once("error", (error) => {
171				if (!rejected) reject(error);
172			});
173			request.once("end", () => {
174				if (rejected) return;
175				try {
176					const raw = Buffer.concat(chunks).toString("utf8");
177					resolve(raw.length === 0 ? undefined : JSON.parse(raw));
178				} catch {
179					reject(new HttpRequestError(400, "Request body must be valid JSON."));
180				}
181			});
182		});
183	}
