265		async function closeSession(
266			session: HttpSession,
267			failureCategory?: "connect_failure" | "startup_failure" | "unknown",
268		): Promise<void> {
269			if (session.closed) return;
270			session.closed = true;
271			for (const [id, current] of sessions) {
272				if (current === session) sessions.delete(id);
273			}
274			for (const response of session.responses) {
275				if (!response.writableEnded) response.destroy();
276			}
277			// The SDK transport closes response streams, but its stateful close path
278			// does not abort the request signal already handed to MCP handlers. Abort
279			// the session-owned lifecycle signal first so active Hevy calls stop too.
280			session.lifecycleController.abort(
281				new DOMException("MCP session closed", "AbortError"),
282			);
283	
284			const results = await Promise.allSettled([
285				Promise.resolve().then(() => session.transport.close()),
286				Promise.resolve().then(() => session.server.close()),
287			]);
288			const errors = results.flatMap((result) =>
289				result.status === "rejected" ? [result.reason] : [],
290			);
291			const succeeded = errors.length === 0;
292			recordMcpSessionTermination(
293				failureCategory && succeeded
294					? failureCategory
295					: resolveSessionTerminationCategory(succeeded, session.context),
296				session.context,
297			);
298			if (errors.length > 0) {
299				throw aggregateErrors(errors, "MCP session cleanup failed.");
300			}
301		}
