314			if (errors.length > 0) throw aggregateErrors(errors, "MCP cleanup failed.");
315			return;
316		}
317	
318		function trackSessionResponse(
319			session: HttpSession,
320			response: ServerResponse,
321		): void {
322			session.responses.add(response);
323			response.once("close", () => {
324				session.responses.delete(response);
325				// A destroyed response means the client disconnected before the
326				// exchange completed. The SDK does not expose a request-scoped signal
327				// for this transport, so evict and close the whole session rather than
328				// leaving an aborted session reusable or poisoning future requests.
329				if (!response.writableEnded && !session.closed) {
330					void closeSession(session).catch((error: unknown) => {
331						cleanupErrors.push(error);
332					});
333				}
334			});
335		}
336	
337		async function handleRequest(
338			request: IncomingMessage,
339			response: ServerResponse,
340		): Promise<void> {
341			if (request.url?.split("?", 1)[0] !== MCP_PATH) {
342				writeJson(response, 404, "Not found");
343				return;
344			}
345			if (
346				!validateHostHeader(
347					request,
348					hostNamesFor(options),
349					expectedPort(options, server),
350					wildcard,
351				)
352			) {
353				writeJson(response, 403, "Invalid Host header");
354				return;
355			}
356			if (!loopback && !isBearerAuthorized(request, bearerToken)) {
357				writeJson(response, 401, "Authorization required");
358				return;
359			}
360	
361			const body =
362				request.method === "POST" ? await readBody(request) : undefined;
363			const initializing = request.method === "POST" && isInitializeRequest(body);
364			const sessionHeader = request.headers["mcp-session-id"];
365			const sessionId =
366				typeof sessionHeader === "string" ? sessionHeader : undefined;
367	
368			if (initializing) {
369				if (sessionId) {
370					writeJson(
371						response,
372						400,
373						"Initialization must not include Mcp-Session-Id.",
374					);
375					return;
376				}
377				const context = createMcpSessionContext(body, "http");
378				recordMcpSessionStart(body, "http", context);
379				let session: HttpSession | undefined;
380				let mcpServer: OwnedMcpServer | undefined;
381				let connected = false;
382				const lifecycleController = new AbortController();
383				const transport = new NodeStreamableHTTPServerTransport({
384					sessionIdGenerator: randomUUID,
385					onsessioninitialized: (id) => {
386						if (session) sessions.set(id, session);
387					},
388				});
389				transport.onclose = () => {
390					if (session) {
391						void closeSession(session).catch((error: unknown) => {
392							cleanupErrors.push(error);
393						});
394					}
395				};
396				try {
397					mcpServer = await createMcpServer({
398						apiKey,
399						lifecycleSignal: lifecycleController.signal,
400					});
401					session = {
402						transport,
403						server: mcpServer,
404						context,
405						lifecycleController,
406						responses: new Set(),
407						closed: false,
408					};
409					await mcpServer.connect(transport);
410					connected = true;
411					trackSessionResponse(session, response);
412					await runWithMcpSessionContext(context, () =>
413						transport.handleRequest(request, response, body),
414					);
415				} catch (error) {
416					lifecycleController.abort(
417						new DOMException("MCP session startup failed", "AbortError"),
418					);
419					console.error(`HTTP session request failed: ${safeDiagnostic(error)}`);
420					let cleanupError: unknown;
421					try {
422						if (session) {
423							await closeSession(
424								session,
425								connected ? "unknown" : "connect_failure",
426							);
427						} else {
428							await closeUnregistered(transport, mcpServer);
429							recordMcpSessionTermination("startup_failure", context);
430						}
431					} catch (cleanupFailure) {
432						cleanupError = cleanupFailure;
433						if (!session) recordMcpSessionTermination("unknown", context);
434					}
435					if (cleanupError) {
436						console.error(`HTTP cleanup failed: ${safeDiagnostic(cleanupError)}`);
437					}
438					if (!response.writableEnded)
439						writeExecutionJson(response, 500, "Internal server error.", error);
440				}
441				return;
442			}
443	
444			if (!sessionId) {
445				writeJson(response, 400, "Mcp-Session-Id header is required.");
446				return;
447			}
448			const session = sessions.get(sessionId);
449			if (!session) {
450				writeJson(response, 404, "Unknown Mcp-Session-Id.");
451				return;
452			}
453			if (request.method !== "DELETE") {
454				trackSessionResponse(session, response);
455			}
456			await runWithMcpSessionContext(session.context, () =>
457				session.transport.handleRequest(request, response, body),
458			);
459		}
460	
461		await new Promise<void>((resolve, reject) => {
462			server.once("error", reject);
463			server.listen(options.port, options.host, () => {
464				server.removeListener("error", reject);
465				resolve();
466			});
467		});
468	
469		let closePromise: Promise<void> | undefined;
470		return {
471			server,
472			close: () => {
473				if (closePromise) return closePromise;
474				closePromise = (async () => {
475					const sessionsToClose = [...sessions.values()];
476					const results = await Promise.allSettled([
477						...sessionsToClose.map((session) => closeSession(session)),
478						closeServer(server),
479					]);
480					sessions.clear();
481					const errors = [
482						...cleanupErrors,
483						...results.flatMap((result) =>
484							result.status === "rejected" ? [result.reason] : [],
485						),
486					];
487					if (errors.length > 0) {
488						throw aggregateErrors(errors, "HTTP server cleanup failed.");
489					}
490				})();
491				return closePromise;
492			},
493		};
494	}

