   354	export function createWorkerHandler(dependencies: WorkerDependencies = {}) {
   355		const resolved = resolveWorkerDependencies(dependencies);
   356	
   357		return async function handleRequest(
   358			request: Request,
   359			env: WorkerEnv,
   360		): Promise<Response> {
   361			const url = new URL(request.url);
   362			if (url.pathname !== MCP_PATH)
   363				return new Response("Not found", { status: 404 });
   364	
   365			const originResult = validateOrigin(request, env);
   366			if (originResult instanceof Response) return originResult;
   367			const origin = originResult;
   368			let hevyApiBaseUrl: string;
   369			try {
   370				hevyApiBaseUrl = resolveHevyApiBaseUrl(env.HEVY_API_BASE_URL);
   371			} catch {
   372				return response("Worker configuration error", 500, origin);
   373			}
   374	
   375			if (request.method === "OPTIONS") {
   376				const headers = origin ? corsHeaders(origin) : new Headers();
   377				headers.set("Access-Control-Allow-Methods", CORS_ALLOWED_METHODS);
   378				headers.set("Access-Control-Allow-Headers", CORS_ALLOWED_HEADERS);
   379				headers.set("Access-Control-Max-Age", "86400");
   380				return new Response(null, { status: 204, headers });
   381			}
   382	
   383			if (request.method !== "POST") {
   384				return response("Method not allowed", 405, origin, {
   385					Allow: CORS_ALLOWED_METHODS,
   386				});
   387			}
   388	
   389			const apiKey = parseBearerApiKey(request.headers.get("authorization"));
   390			if (!apiKey) {
   391				return response("Unauthorized", 401, origin, {
   392					"WWW-Authenticate": "Bearer",
   393				});
   394			}
   395	
   396			const deadline = Date.now() + WORKER_INVOCATION_TIMEOUT_MS;
   397			let validation: HevyApiKeyValidation;
   398			try {
   399				validation = await validateHevyApiKey(
   400					apiKey,
   401					hevyApiBaseUrl,
   402					resolved.createValidationClient,
   403					{
   404						signal: request.signal,
   405						deadline,
   406					},
   407				);
   408			} catch (error) {
   409				return executionHttpResponse(
   410					error,
   411					"Unable to validate the Hevy API key",
   412					502,
   413					origin,
   414				);
   415			}
   416			if (validation === "invalid") {
   417				return response("Unauthorized", 401, origin, {
   418					"WWW-Authenticate": "Bearer",
   419				});
   420			}
   421	
   422			return withCors(
   423				await serveMcpRequest(
   424					request,
   425					apiKey,
   426					hevyApiBaseUrl,
   427					resolved,
   428					deadline,
   429				),
   430				origin,
   431			);
   432		};
   433	}
