    47	function safeErrorAttributes(observation: HevyRequestObservation): {
    48		error_category?: string;
    49		error_code?: string;
    50	} {
    51		if (!observation.error) return {};
    52		const code = observation.error.code;
    53		return {
    54			error_category: observation.error.category ?? "HevyHttpError",
    55			...(code && SAFE_OBSERVATION_CODES.has(code) ? { error_code: code } : {}),
