    59	function startApiSpan(start: HevyRequestStart) {
    60		const sessionId = getCurrentMcpSessionId();
    61		return tracer.startSpan(`hevy.api.${start.method}`, {
    62			attributes: {
    63				"mcp.span.category": "api",
    64				"http.request.method": start.method,
    65				"hevy.api.endpoint": start.endpoint,
    66				"hevy.api.retry_count_bucket": bucketCount(start.retryCount),
    67				"mcp.transport": getCurrentMcpTransport(),
    68				...(sessionId ? { "mcp.session.id": sessionId } : {}),
    69			},
    70		});
    71	}
    72	function finishApiSpan(span: Span, observation: HevyRequestObservation): void {
    73		const errorAttributes = safeErrorAttributes(observation);
    74		if (observation.status > 0) {
    75			span.setAttribute("http.response.status_code", observation.status);
    76		}
    77		for (const [key, value] of Object.entries(
    78			projectExecutionAttributes(observation),
    79		)) {
    80			span.setAttribute(key, value);
    81		}
    82		if (observation.expectedReason) {
    83			span.setAttribute("hevy.api.expected_reason", observation.expectedReason);
    84		}
    85		for (const [key, value] of Object.entries(errorAttributes)) {
    86			span.setAttribute(key, value);
    87		}
    88		span.setStatus({
    89			code:
    90				observation.outcome === "success" || observation.outcome === "expected"
    91					? SpanStatusCode.OK
    92					: SpanStatusCode.ERROR,
    93		});
    94		if (observation.outcome !== "success" && observation.outcome !== "expected") {
    95			span.addEvent("hevy.api.failure", {
    96				"error.category": errorAttributes.error_category ?? "HevyHttpError",
    97				...(errorAttributes.error_code
    98					? { "error.code": errorAttributes.error_code }
    99					: {}),
   100			});
   101		}
   102		span.end();
   103	}
