   106	export function createNodeHevyClientOptions(): HevyClientOptions {
   107		const rawTimeout = process.env.HEVY_MCP_API_TIMEOUT;
   108		const parsedTimeout = rawTimeout ? Number(rawTimeout) : Number.NaN;
   109		const timeoutMs =
   110			Number.isFinite(parsedTimeout) && parsedTimeout > 0
   111				? Math.floor(parsedTimeout)
   112				: undefined;
   113		return {
   114			...(timeoutMs ? { timeoutMs } : {}),
   115			onRequestStart(start) {
   116				const span = startApiSpan(start);
   117				return {
   118					run<T>(operation: () => Promise<T>) {
   119						return context.with(trace.setSpan(context.active(), span), operation);
   120					},
   121					finish(observation) {
   122						finishApiSpan(span, observation);
   123					},
   124				};
   125			},
   126			onRequestComplete(observation) {
   127				const retryCountBucket = bucketCount(observation.retryCount);
   128				const errorAttributes = safeErrorAttributes(observation);
   129				const metricEndpoint = normalizeHevyMetricEndpoint(observation.endpoint);
   130				const metricExecutionAttributes = projectExecutionAttributes(
   131					observation,
   132					"metric",
   133				);
   134				apiCalls.add(1, {
   135					method: observation.method,
   136					endpoint: metricEndpoint,
   137					status_code: observation.status,
   138					retry_count_bucket: retryCountBucket,
   139					...metricExecutionAttributes,
   140					transport: getCurrentMcpTransport(),
   141					...(observation.expectedReason
   142						? { expected_reason: observation.expectedReason }
   143						: {}),
   144					...errorAttributes,
   145				});
   146				apiDuration.record(observation.durationMs, {
   147					method: observation.method,
   148					endpoint: metricEndpoint,
   149					retry_count_bucket: retryCountBucket,
   150					...metricExecutionAttributes,
   151					transport: getCurrentMcpTransport(),
   152					...(observation.expectedReason
   153						? { expected_reason: observation.expectedReason }
   154						: {}),
   155					...errorAttributes,
   156				});
   157				debugLog("api_response", {
   158					method: observation.method,
   159					endpoint: observation.endpoint,
   160					durationMs: observation.durationMs,
   161					status: observation.status || null,
   162					retryCountBucket,
   163					outcome: observation.outcome,
   164					...errorAttributes,
   165				});
   166			},
   167			onRetryWait(observation) {
   168				const sessionId = getCurrentMcpSessionId();
   169				const span = tracer.startSpan("hevy.api.retry_wait", {
   170					attributes: {
   171						"mcp.span.category": "api",
   172						"http.request.method": observation.method,
   173						"hevy.api.retry_count_bucket": bucketCount(observation.retryCount),
   174						"hevy.api.retry_wait_ms": Math.max(
   175							0,
   176							Math.min(5_000, observation.delayMs),
   177						),
   178						...(sessionId ? { "mcp.session.id": sessionId } : {}),
   179					},
   180				});
   181				return { finish: () => span.end() };
   182			},
   183		};
   184	}
