    33	export type ProcessExceptionSource = {
    34		on(
    35			event: "uncaughtExceptionMonitor" | "unhandledRejection",
    36			listener: (error: unknown) => void,
    37		): void;
    38		removeListener(
    39			event: "uncaughtExceptionMonitor" | "unhandledRejection",
    40			listener: (error: unknown) => void,
    41		): void;
    42	};
    43	
    44	const PROCESS_FAILURE_TAXONOMY = {
    45		uncaughtException: "uncaught_exception",
    46		unhandledRejection: "unhandled_rejection",
    47	} as const;
    48	
    49	export function installProcessExceptionTracking(
    50		processLike: ProcessExceptionSource = process,
    51	): () => void {
    52		if (!telemetryEnabled) return () => {};
    53		const recordProcessException = (
    54			source: keyof typeof PROCESS_FAILURE_TAXONOMY,
    55			error: unknown,
    56		) => {
    57			try {
    58				tracer.startActiveSpan(
    59					`mcp.process.${source}`,
    60					{ attributes: { "mcp.span.category": "process" } },
    61					(span) => {
    62						try {
    63							captureFailure(error, {
    64								kind: "process",
    65								attributes: {
    66									"exception.source": source,
    67									"mcp.failure.phase": PROCESS_FAILURE_TAXONOMY[source],
    68									"error.type": "MCP_PROCESS_EXCEPTION",
    69									"error.category": "McpProcessFailure",
    70								},
    71								span,
    72							});
    73						} finally {
    74							span.end();
    75						}
    76					},
    77				);
    78			} catch {
    79				// Process telemetry must never affect Node's lifecycle.
    80			}
    81		};
    82		const uncaughtException = (error: unknown) =>
    83			recordProcessException("uncaughtException", error);
    84		const unhandledRejection = (error: unknown) =>
    85			recordProcessException("unhandledRejection", error);
    86		processLike.on("uncaughtExceptionMonitor", uncaughtException);
    87		processLike.on("unhandledRejection", unhandledRejection);
    88		let cleaned = false;
    89		return () => {
    90			if (cleaned) return;
    91			cleaned = true;
    92			processLike.removeListener("uncaughtExceptionMonitor", uncaughtException);
    93			processLike.removeListener("unhandledRejection", unhandledRejection);
    94		};
    95	}
