   219	export async function flushTelemetry(timeoutMs = 1_000): Promise<void> {
   220		if (!telemetryEnabled) {
   221			return;
   222		}
   223	
   224		const flushPromise = Promise.allSettled([
   225			...(tracerProvider ? [tracerProvider.forceFlush()] : []),
   226			...(meterProvider ? [meterProvider.forceFlush()] : []),
   227			Sentry.flush(timeoutMs),
   228		]);
   229		let timeout: ReturnType<typeof setTimeout> | undefined;
   230		const timeoutPromise = new Promise<void>((resolve) => {
   231			timeout = setTimeout(resolve, timeoutMs);
   232		});
   233		try {
   234			await Promise.race([flushPromise, timeoutPromise]);
   235		} finally {
   236			clearTimeout(timeout);
   237		}
   238	}
