 51	async function parseMcpResponse(response: Response) {
 52		const text = await response.text();
 53		if (response.headers.get("content-type")?.includes("text/event-stream")) {
 54			const data = text
 55				.split("\n")
 56				.find((line) => line.startsWith("data: "))
 57				?.slice(6);
 58			if (!data) throw new Error(`Missing SSE data: ${text}`);
 59			return JSON.parse(data) as Record<string, unknown>;
 60		}
 61		return JSON.parse(text) as Record<string, unknown>;
 62	}
