     1	/**
     2	 * Runtime-neutral execution control shared by every Hevy adapter.
     3	 *
     4	 * The client owns this vocabulary so adapters can only present the same
     5	 * outcome; they cannot accidentally grow incompatible retry/error taxonomies.
     6	 */
     7	
     8	export type HevyOperationSafety =
     9		| "read"
    10		| "idempotent-write"
    11		| "non-idempotent-write";
    12	
    13	export type HevyRequestPhase =
    14		| "before-dispatch"
    15		| "dispatch"
    16		| "response-headers"
    17		| "response-content"
    18		| "backoff"
    19		| "completed";
    20	
    21	export type HevyCommitState = "not_sent" | "confirmed" | "unknown";
    22	
    23	export type HevyExecutionOutcome =
    24		| "success"
    25		| "expected"
    26		| "retryable_failure"
    27		| "terminal_failure"
    28		| "cancelled"
    29		| "deadline_exceeded";
    30	
    31	export interface HevyExecutionOutcomeDetails {
    32		readonly outcome: HevyExecutionOutcome;
    33		readonly phase: HevyRequestPhase;
    34		readonly operation_safety: HevyOperationSafety;
    35		readonly commit_state: HevyCommitState;
    36		readonly safe_to_retry: boolean;
    37		readonly status?: number;
    38		readonly code?: string;
    39	}
    40	
    41	/** Caller-owned control for one logical operation (not one retry attempt). */
    42	export interface HevyExecutionControl {
    43		readonly signal?: AbortSignal;
    44		/** Absolute epoch milliseconds. It is never reset for a retry or page. */
    45		readonly deadline?: number;
    46	}
    47	
    48	export interface HevyExecutionOptions extends HevyExecutionControl {}
    49	
    50	/** Request options shared by the curated client and generated adapters. */
    51	export interface HevyRequestOptions extends HevyExecutionOptions {}
    52	
    53	export function isDeadlineExceeded(deadline: number | undefined): boolean {
    54		return deadline !== undefined && Date.now() >= deadline;
    55	}
    56	
    57	export function remainingDeadlineMs(deadline: number | undefined): number {
    58		return deadline === undefined
    59			? Number.POSITIVE_INFINITY
    60			: deadline - Date.now();
    61	}
    62	
    63	export function operationSafetyForMethod(method: string): HevyOperationSafety {
    64		const normalizedMethod = method.toUpperCase();
    65		if (["GET", "HEAD", "OPTIONS"].includes(normalizedMethod)) {
    66			return "read";
    67		}
    68		if (["PUT", "DELETE"].includes(normalizedMethod)) {
    69			return "idempotent-write";
    70		}
    71		return "non-idempotent-write";
    72	}
    73	
    74	export function canRetryOperation(
    75		safety: HevyOperationSafety,
    76		phase: HevyRequestPhase,
    77	): boolean {
    78		if (safety === "non-idempotent-write") return false;
    79		return (
    80			phase === "before-dispatch" ||
    81			phase === "dispatch" ||
    82			phase === "response-headers" ||
    83			phase === "response-content" ||
    84			phase === "backoff"
    85		);
    86	}
    87	
    88	export function commitStateFor(
    89		safety: HevyOperationSafety,
    90		phase: HevyRequestPhase,
    91		confirmed: boolean,
    92	): HevyCommitState {
    93		if (safety === "read") return confirmed ? "confirmed" : "not_sent";
    94		if (confirmed) return "confirmed";
    95		return phase === "before-dispatch" ? "not_sent" : "unknown";
    96	}
    97	
    98	/**
    99	 * Build a signal that follows both caller cancellation and one absolute
   100	 * deadline. The returned cleanup function must be called when the operation
   101	 * completes so a long-lived server does not retain timers/listeners.
   102	 */
   103	export function createExecutionSignal(control: HevyExecutionControl): {
   104		signal: AbortSignal;
   105		abort: (reason?: unknown) => void;
   106		cleanup: () => void;
   107		deadlineTriggered: () => boolean;
   108	} {
   109		const controller = new AbortController();
   110		let deadlineTriggered = false;
   111		const abortFromCaller = () => {
   112			if (!controller.signal.aborted) controller.abort(control.signal?.reason);
   113		};
   114		if (control.signal?.aborted) abortFromCaller();
   115		else
   116			control.signal?.addEventListener("abort", abortFromCaller, { once: true });
   117		let timer: ReturnType<typeof setTimeout> | undefined;
   118		if (control.deadline !== undefined) {
   119			const delay = Math.max(0, control.deadline - Date.now());
   120			timer = setTimeout(() => {
   121				deadlineTriggered = true;
   122				if (!controller.signal.aborted) {
   123					controller.abort(
   124						new DOMException("Operation deadline exceeded", "TimeoutError"),
   125					);
   126				}
   127			}, delay);
   128		}
   129		return {
   130			signal: controller.signal,
   131			abort: (reason?: unknown) => {
   132				if (!controller.signal.aborted) controller.abort(reason);
   133			},
   134			cleanup: () => {
   135				if (timer !== undefined) clearTimeout(timer);
   136				control.signal?.removeEventListener("abort", abortFromCaller);
   137			},
   138			deadlineTriggered: () => deadlineTriggered,
   139		};
   140	}
   141	
   142	export function isAbortLike(error: unknown): boolean {
   143		if (!(error instanceof Error)) return false;
   144		return error.name === "AbortError" || error.name === "TimeoutError";
   145	}

