   100	function getPeriod(weeks: number): {
   101		startDate: string;
   102		endDate: string;
   103	} {
   104		const end = new Date();
   105		const start = new Date(end);
   106		start.setUTCDate(start.getUTCDate() - weeks * 7);
   107		return { startDate: utcDateString(start), endDate: utcDateString(end) };
   108	}
   109	
   110	function durationSeconds(workout: Workout): number | undefined {
   111		if (!workout.start_time || !workout.end_time) return undefined;
   112		const duration =
   113			new Date(workout.end_time).getTime() -
   114			new Date(workout.start_time).getTime();
   115		return Number.isFinite(duration) && duration >= 0
   116			? Math.floor(duration / 1000)
   117			: undefined;
   118	}
