   127			...(workout.title ? { title: workout.title } : {}),
   128			...(workout.start_time ? { start_time: workout.start_time } : {}),
   129			...(workout.end_time ? { end_time: workout.end_time } : {}),
   130			...(elapsedSeconds === undefined
   131				? {}
   132				: { duration_seconds: elapsedSeconds }),
   133			exercise_count: exercises.length,
   134			set_count: exercises.reduce(
   135				(total, exercise) => total + (exercise.sets?.length ?? 0),
