   148				: { weight_kg: measurement.weight_kg }),
   149			...(measurement.lean_mass_kg == null
   150				? {}
   151				: { lean_mass_kg: measurement.lean_mass_kg }),
   152			...(measurement.fat_percent == null
   153				? {}
   154				: { fat_percent: measurement.fat_percent }),
   155		};
   156	}
