463	/** Build bounded diagnostic metadata with no raw messages, payloads, or URLs. */
464	export function createSafeErrorDiagnostic(error: unknown): SafeErrorDiagnostic {
465		try {
466			const diagnostic: SafeErrorDiagnostic = { category: classifyError(error) };
467			const code = getSafeCode(error);
468			const status = extractErrorStatus(error);
469			const method = getSafeMethod(error);
470			const endpoint = getSafeEndpoint(error);
471			const frames = parseSafeStackFrames(error);
472			if (code) diagnostic.code = code;
473			if (status !== undefined) diagnostic.status = status;
474			if (method) diagnostic.method = method;
475			if (endpoint) diagnostic.endpoint = endpoint;
476			if (frames) diagnostic.frames = frames;
477			Object.assign(diagnostic, getExecutionFields(error));
478			return diagnostic;
479		} catch {
480			return { category: "UnknownError" };
481		}
482	}
