186	function resolveHevyApiBaseUrl(value: string | undefined): string {
187		if (value === undefined) return HEVY_API_BASE_URL;
188	
189		let url: URL;
190		try {
191			url = new URL(value);
192		} catch {
193			throw new TypeError("Invalid Hevy API base URL");
194		}
195		if (
196			(url.protocol !== "http:" && url.protocol !== "https:") ||
197			url.username ||
198			url.password ||
199			url.search ||
200			url.hash ||
201			url.pathname.replace(/\/+$/, "")
202		) {
203			throw new TypeError("Invalid Hevy API base URL");
204		}
205		return url.origin;
206	}
