292	async function validateHevyApiKey(
293		apiKey: string,
294		hevyApiBaseUrl: string,
295		createValidationClient: ResolvedWorkerDependencies["createValidationClient"],
296		options?: HevyRequestOptions,
297	): Promise<HevyApiKeyValidation> {
298		try {
299			const validationDeadline = Math.min(
300				options?.deadline ?? Number.POSITIVE_INFINITY,
301				Date.now() + WORKER_VALIDATION_TIMEOUT_MS,
302			);
303			await createValidationClient(apiKey, hevyApiBaseUrl).getUserInfo({
304				...options,
305				deadline: validationDeadline,
306			});
307			return "valid";
308		} catch (error) {
309			if (options?.signal?.aborted) throw error;
310			if (isHevyHttpError(error) && error.outcome === "deadline_exceeded") {
311				throw error;
312			}
313			if (
314				isHevyHttpError(error) &&
315				(error.status === 401 || error.status === 403)
316			) {
317				return "invalid";
318			}
319			throw error;
320		}
321	}
