461	async function handleAuthorizedMcpRequest<Env>(
462		request: Request,
463		env: Env,
464		ctx: object,
465		dependencies: HevyOAuthDependencies<Env>,
466	): Promise<Response> {
467		const deadline = Date.now() + WORKER_INVOCATION_TIMEOUT_MS;
468		const props = (ctx as { props?: Partial<HevyGrantProps> } | null | undefined)
469			?.props;
470		const apiKey =
471			typeof props?.hevyApiKey === "string" ? props.hevyApiKey : null;
472		if (!apiKey) return oauthUnauthorizedResponse(request);
473	
474		let validation: HevyOAuthValidation;
475		try {
476			validation = await dependencies.validateApiKey(
477				apiKey,
478				env,
479				request.signal,
480				deadline,
481			);
482		} catch (error) {
483			return jsonValidationFailure(error, request);
484		}
485		if (validation === "config-error") {
486			return jsonConfigErrorResponse();
487		}
488		if (validation === "invalid") return oauthUnauthorizedResponse(request);
489		return dependencies.serveMcp(request, env, apiKey, deadline);
490	}
