 28	function openStream(
 29		port: number,
 30		headers: Record<string, string>,
 31	): Promise<{ ended: Promise<void> }> {
 32		return new Promise((resolve, reject) => {
 33			const client = request(
 34				{
 35					host: "127.0.0.1",
 36					port,
 37					path: "/mcp",
 38					method: "GET",
 39					headers: { Accept: "text/event-stream", ...headers },
 40				},
 41				(response) => {
 42					const ended = new Promise<void>((finish) => {
 43						response.once("end", finish);
 44						response.once("close", finish);
 45					});
 46					resolve({ ended });
 47				},
 48			);
 49			client.once("error", reject);
 50			client.end();
 51		});
 52	}
