 54	function call(
 55		port: number,
 56		method: string,
 57		body?: unknown,
 58		extraHeaders: Record<string, string> = {},
 59	): Promise<HttpResult> {
 60		return new Promise((resolve, reject) => {
 61			const payload = body === undefined ? undefined : JSON.stringify(body);
 62			const client = request(
 63				{
 64					host: "127.0.0.1",
 65					port,
 66					path: "/mcp",
 67					method,
 68					headers: {
 69						Accept: "application/json, text/event-stream",
 70						...(payload ? { "Content-Type": "application/json" } : {}),
 71						...extraHeaders,
 72					},
 73				},
 74				(response) => {
 75					const chunks: Buffer[] = [];
 76					response.on("data", (chunk: Buffer) => chunks.push(chunk));
 77					response.once("end", () =>
 78						resolve({
 79							statusCode: response.statusCode,
 80							headers: response.headers,
 81							body: Buffer.concat(chunks).toString("utf8"),
 82						}),
 83					);
 84				},
 85			);
 86			client.once("error", reject);
 87			if (payload) client.write(payload);
 88			client.end();
 89		});
 90	}
