 98	function jsonBody(result: HttpResult): Record<string, unknown> {
 99		const json = result.body.startsWith("event:")
100			? result.body
101					.split("\n")
102					.filter((line) => line.startsWith("data:"))
103					.map((line) => line.slice("data:".length).trim())
104					.join("\n")
105			: result.body;
106		if (!json) throw new Error(`empty response: ${JSON.stringify(result)}`);
107		return JSON.parse(json) as Record<string, unknown>;
108	}
